        return 0 <= r < H and 0 <= c < W
    comps = []
    for r in range(H):
        for c in range(W):
            if g[r][c] == 1:
                stack = [(r, c)]
                g[r][c] = 0
                cells = []
                while stack:
                    x, y = stack.pop()
                    cells.append((x, y))
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = (x + dx, y + dy)
                        if inb(nx, ny) and g[nx][ny] == 1:
                            g[nx][ny] = 0
                            stack.append((nx, ny))
                comps.append(cells)
    for cells in comps:
        if not cells:
            continue
        s = set(cells)
        holes = []
        seen_hole = set()
