                        x, y = stack.pop()
                        comp_bg.append((x, y))
                        for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                            if not inb(nx, ny):
                                closed = False
                                continue
                            if (nx, ny) in seen_hole or grid[nx][ny] != 4:
                                continue
                            seen_hole.add((nx, ny))
                            stack.append((nx, ny))
                    if closed:
                        holes.extend(comp_bg)
        hole_set = set(holes)
        interior = s | hole_set
        for r, c in s:
            out[r][c] = 8 if hole_set else 1
        for r, c in holes:
            out[r][c] = 6
        border = set()
        for r, c in interior:
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
